INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter15-1857-revolt-in-hyderabad', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p1", "partName": "Dalhousie and the Doctrine of Lapse", "bodyMd": "**Lord Dalhousie''s Arrival and Expansion Policy:**\n\n*   Dalhousie took charge as Governor-General of India on **12 January 1849**, in his 35th year\n*   From the moment he arrived, he pursued a policy of territorial expansion\n*   Under Company rule, states had fallen into three categories: independent states, subordinate-allied states, and dependent states; Dalhousie scrapped this arrangement and introduced three new classifications instead\n*   Independent states such as **Berar, Sikkim, and Punjab** were defeated in war and absorbed into the British Empire\n*   Contingent forces were stationed on large states like the Nizam''s, and their most fertile territories were seized as payment\n*   Dependent states such as Ayodhya were annexed on the pretext of misgovernance\n*   The pensions of the rulers of **Karnataka and Thanjavur** were stopped, and the Mughal Emperor himself was reduced to a British pensioner\n*   Dalhousie''s policies brought comfort only to the British while plunging India into turmoil\n*   He left India heartbroken on **5 March 1856**, suffered from heart trouble, and died in a state of destitution on **19 December 1866**\n\n**Two Systems of Inheritance:**\n\n*   Two inheritance principles were in practice in India: **\"Warasin\"** and **\"Janshin\"**\n*   Under **Warasin**, when a king died, the kingdom passed to his sons or close blood relatives\n*   Under **Janshin**, a family without natural heirs could adopt a son and pass on authority to him\n*   Dalhousie abolished the Janshin system, and by doing so annexed numerous states\n*   This policy of non-recognition struck at the roots of many kingdoms, and dissatisfaction spread across the country like a forest fire as a result\n\nDalhousie''s abolition of the adoption principle led directly to a wave of annexations that fuelled nationwide resentment:\n\n*   The ruler of **Jhansi**, Gangadharrao, died in 1858; Jhansi state was under Peshwa rule\n*   Since Gangadharrao had no children, he had adopted a boy; Dalhousie rejected the petition for permission submitted by his wife, **Rani Lakshmibai**, for this adoption to be recognized\n*   In 1855, the Karnataka Nawab **Mahammad Gaur** died; orders were issued denying his heir a pension\n*   In 1851, the second Peshwa **Bajirao** died; while he was alive, the British had arranged a pension of 8 lakh rupees per year for him\n*   They decided this pension would not continue for his adopted son, **Nanasaheb**\n*   In 1851, the Raja of Thanjavur died; while alive, he had declared his second daughter as his heir, since women were not eligible to inherit paternal property\n*   Thanjavur was accordingly annexed\n*   **Sambalpur** was among the earliest states to face this treatment\n\nFearing that they too might one day be swallowed up in this manner, other states — even those not directly threatened by these policies — grew apprehensive and were fully prepared to rebel when the moment came.\n\n**Economic Fallout:**\n\n*   As so many states were abolished at once, people employed there in various occupations became unemployed\n*   Artists and scholars dependent on royal patronage were left without support\n*   Meanwhile, Company officials, aiming to bring farmers into the army, raised land taxes excessively", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p2", "partName": "Background — The Fifth Nizam and the Political Climate of 1857", "bodyMd": "*   **Afzal-ud-Daula** of the Asaf Jahi dynasty became the 5th ruler of Hyderabad State in 1857, inheriting **Salar Jung** as his exceptionally able Minister\n*   The fifth Nizam ruled for only 12 years — the shortest reign of any Nizam — yet this brief period saw some of the most consequential events in the state''s history\n*   His accession coincided with a powerful explosion across India: the 1857 Revolt\n*   By this point the British had taken more than a hundred years to secure their position in India, and their authoritarian administration had generated deep dissatisfaction among conservative Indians, described as resembling \"fire covered by water\"\n\n**Grievances Under British Administration:**\n\n*   Peasants lost their lands and became laborers; craftsmen were forced to abandon their customary professions\n*   Employees became unemployed, and the revenue administration left deep dissatisfaction in Indian village institutions\n*   Corruption in the Revenue and Police Departments caused widespread suffering\n*   The British kept the local rulers and kings at a distance, and the Princely States (Samasthanams) were crushed under British administrative control\n*   Dalhousie''s succession system (Doctrine of Lapse) evoked deep distrust among local rulers, as it was seen as a tactic to annex kingdoms and Samasthanams\n\n**Symbolic Grievances:**\n\n*   The Mughal sovereign **Bahadurshah Zafar** was forcibly removed from the Red Fort and ordered by Dalhousie to spend his time in Mehrauli\n    \n*   Lord Canning proclaimed Bahadurshah Zafar the last Emperor, declaring his successors would not inherit his titles — a severe blow to Mughal self-respect after nearly 300 years of rule\n    \n*   Rulers of princely states became suspects in British eyes\n    \n*   Hindus feared religious conversion by Christian missionaries operating through education\n    \n*   Indian soldiers (Sepoys) faced torture and humiliation, and there was resentment over differences in promotions, pay, and allowances between British and Indian soldiers\n    \n*   This accumulated dissatisfaction reached a flashpoint, and the Enfield rifle cartridge controversy provided the spark\n    \n*   Mutiny broke out first in Meerut, and lacking time to organize a system to contain it, the British faced battles across North India, with help for the rebels coming from rulers of princely states", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p3", "partName": "The Delayed Onset of Revolt in Hyderabad", "bodyMd": "*   Unlike North India, the revolt did not break out instantly in Hyderabad, though people showed extreme displeasure toward the British there too\n*   The South was strategically sensitive for the English Government, which remained watchful of antagonism building in Hyderabad against the British\n\n**Early Armed Resistance:**\n\n*   Alija and his associates Sadasiva Reddy and Raja Mahipatram had earlier attempted armed rebellion at different times\n*   This resistance was connected to the origins of **Mubariz-ud-Daula**, son of Nasiruddaula\n\n### The Wahabi Movement''s Influence\n\n*   Initiated by **Abdul Wahab Nejdi** of Saudi Arabia, the Wahabi movement aimed to resurrect the greatness of Islam and entered India in 1820 with Peshawar (Afghanistan) as its center\n*   **Sayyed Ahmed Brailvi** started the movement in India, opposing English rule and Christian influence\n*   In Hyderabad, the movement was carried on by Mubariz-ud-Daula and his followers, and by **Ghulam Rasool Khan**, Nawab of Kurnool, against the British\n*   Mubariz-ud-Daula was caught and imprisoned; his followers, though also imprisoned, were released before 1857 but had already succeeded in spreading anti-British sentiment\n\n### Resentment\n\n*   **Berar**, part of the Nizam''s state, was taken over by the English in 1853 as debt repayment, badly damaging the Nizam''s finances — the British needed the cotton-rich region to feed textile mills in England\n*   The early losses of **Kurnool and Berar**, combined with lingering resentment over the death of Tipu Sultan in Mysore, deepened anti-British feeling\n*   Parallel unrest elsewhere fed the mood: the **Mopla Muslims** revolted in Kerala inspired by the Wahabis, and Muslims of Madras considered following suit; followers of **Tantiya Tope**, disguised as mendicants and saints, moved through Hyderabad preaching against the British\n*   Many soldiers lost jobs as state army branches were disbanded, breeding hatred toward the British; some nobles also showed hostility", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p4", "partName": "The Strategic Stakes for the British", "bodyMd": "*   Among nearly 500 princely states in the country, Hyderabad was the largest, occupying a position described as the \"heart of South India\"\n*   The British feared that if revolt broke out in the Nizam''s kingdom, it could turn the region from Nagpur to Madras into a \"fire furnace\"\n*   With 15 per cent of Hyderabad''s population Muslim, and large Tamil, Kannadiga, and Marathi communities present, the British feared that if the Nizam supported the rebel cause, the entire Muslim population of South India might revolt and Marathwada, Madras, and Mysore could follow\n*   Unless the Nizam actively helped crush the revolt, they believed the wider uprising could not be contained\n*   The Resident is recorded as worrying that \"if Nizam was lost, then everything was lost\"\n\n**British Strategy:**\n\n*   The British closely monitored the Nizam''s decisions and worked to keep him aligned with them\n*   They promised to write off his loan and return Berar once the revolt ended\n*   In response, the Nizam declared his trustworthiness, and even at his death Nasir-ud-Daula advised his son to remain loyal to the English\n*   Through this maneuvering by Salar Jung, Hyderabad was kept safe for the British from the mutineers", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p5", "partName": "The Hyderabad Army in 1857", "bodyMd": "By 1857, the Hyderabad Army had been considerably reduced:\n\n| Force | Strength | Notes |\n|---|---|---|\n| Main battalion | ~30,000 men | In disorder, weak discipline, mostly hired soldiers |\n| Hyderabad Contingent | 10,000 soldiers | Organized, trained, armed; commanded by ~80 European officers |\n| Nizam''s Army (native soldiers) | Not more than 30,000 men | Under Jamedars, mostly Sikhs, Arabs, and Rohillas; not used regularly |\n\n*   The **Contingent Army** was stationed across Elichpur, Aurangabad, Mominabad, Gulbarga, Hingoli, Bollaram, Warangal, Maktal, Lingasugur, and the hilly tracts of Buldana, moving between locations as required", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p6", "partName": "The Jihad Posters Episode", "bodyMd": "*   Within a month of Afzal-ud-Daula taking the throne, provocative posters appeared on the walls of the capital, spreading across mosques and populous areas\n\n**Contents of the Posters:**\n\n*   Declared that delaying the killing of a \"Christian Kafir\" would result in excommunication from Muslim society\n    \n*   Urged Tahaniyat Ali Khan Bahadur and Afzal-ud-Daula to gather Muslims, suppress the \"Kaffirs,\" and march to Delhi with the promised support of Allah and the Prophet\n    \n*   Called on the king and Diwan to join the movement against Christians in the name of the Prophet, or else \"wear bangles\" and face humiliation, and warned that non-participants would be reduced to road repair workers within a year\n    \n*   Claimed a diktat of the Prophet demanding public reading of the notice, threatening that seven generations of descendants would be cursed for non-compliance\n    \n*   Called for Maulvies to issue Fatwas compelling Zamindars and Qazis to declare war on the English\n    \n*   Declared that anyone dying in the cause — Poor, Rich, Maulvi, Qazi, Mufti, Kotwal, or Subedar alike — would become a Ghazi and find a place in the sacred world\n    \n*   Set a date: all Muslims were to congregate at **Mecca Masjid** on Friday, 25th Shaval 1273, and proceed from there\n    \n*   The rage stirred against the English united Hindus and Muslims at this juncture, and the British grew fearful, moving to mobilize their forces", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p7", "partName": "Rebellion by the Aurangabad Contingent Force", "bodyMd": "**Timeline:**\n\n1.  **May 1857** — Due to the critical condition in North Central India, the British mobilized as many men as possible; the Third Cavalry of Hyderabad was sent to Malegaon at the request of the Bombay Government\n2.  **11 June 1857** — The First Cavalry under Capt. **H.D. Abbott** was sent from Mominabad to Aurangabad as a replacement\n3.  When the First Cavalry reached **Chota Pimpalgaon** (14 km from Aurangabad), the horse-riders suspected a conspiracy to send them far from Aurangabad, deepening their doubts\n4.  They reached Aurangabad and were lodged in **Kala Chabutra**; Captain Abbott, seeking to verify the mood, learned from **Risaladar Mohammed Buran** that Aurangabad was not their final destination and longer travel awaited\n5.  The furious cavalrymen chanted the Mughal Emperor''s name and shouted the slogan **\"Deen ke upar kamar nahi bandenge\"** (we won''t gird our loins against religion), refusing to go beyond the Nizam''s boundary\n6.  **14 June 1857** — Abbott called a meeting of all Jamedars and ordered the Cavalry shifted to **Amba**; Cavalry and Infantry were lodged separately near the river Kaum\n    *   Officers sent their families to safety and sought help from Poona and Maggur\n    *   Secret parleys and signals were exchanged between Infantry and Cavalry, and Burhanbooks of the Third Cavalry informed Abbott that soldiers had waved a green flag\n7.  **24 June 1857** — Additional forces under **Major General Woodburn** arrived from Ahmednagar: 14 light dragoons, cannons with European gunmen, and 25 Bombay Infantry\n\n**Suppression:**\n\n*   Mutineers were lined up for inquiry; **Jamedar Amir Khan**, first named, caused commotion among the soldiers, and Woodburn opened fire\n*   Many cavalrymen of the First and Second Cavalry were declared guilty and disarmed — Amir Khan escaped in the chaos\n*   **Dafedar Fida Ali** fired at Abbott but missed, and was later hanged after trial\n*   The leaders of this uprising, named elsewhere as **Ameer Khan and Waheed Khan**, had a reward of **2,000 rupees** each announced by the British Government for their capture.\n\n**Casualties/Punishment:**\n\n*   One Risaladar, three Jamedars, nine Dafedars, 76 Troopers, and four Trumpet blowers were involved\n*   Of these, 21 persons were fired upon and killed and three were shot with guns\n*   Some were exiled, some whipped, and some removed from service; the disloyal regiment divisions were disarmed, released, and sent away\n\n**Aftermath at Buldana:**\n\n*   Cavalrymen of the Third Cavalry at Buldana grew angry on hearing these developments\n*   The Third Cavalry, under **Lt. Lenox**, was confronted by **Capt. Gall** with 25 Bombay Native Infantry, causing outrage\n*   Thirteen p' WHERE chapter_slug = 'telangana-history-en-chapter15-1857-revolt-in-hyderabad';
UPDATE theory_content SET concepts_json = concepts_json || 'ersons escaped from Buldava under **Jamedar Chidakhan**, reaching Hyderabad after 20 days in July, hoping the Hyderabad Government would shelter them\n*   Instead, the Government announced a **reward of 3,000** on Chidakhan\n*   When the group entered Hyderabad, **Salar Jung arrested them** and sent them to the Residency for trial, along with Chidakhan''s followers", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p8", "partName": "Attack on the Residency", "bodyMd": "**Backdrop:**\n\n*   News of Chidakhan''s arrest spread rapidly; people congregated in mosques with emotional speeches\n*   Salar Jung dispersed them using Arab troops but warned the Resident that the Residency might be attacked\n*   Organizers sent four Maulvies to the King demanding Chidakhan''s release, threatening to attack the Residency if refused\n*   When their demand went unmet, an attack was planned for **17 July 1857**\n\n**Defensive Preparations by Salar Jung and Col. Davidson:**\n\n*   Contingent troops in Hyderabad were retained only to the extent required, with the rest removed\n*   Six cannons and one Cavalry squad were shifted to the Residency\n*   The day before the attack, additional armory was mobilized: three cannons, two mortars, one detailed Cannon firemen unit, one cavalry troop, 25 troopers of the Madras Light Infantry, and 200 foot soldiers of the Madras Regiment\n*   Every entry point of the Residency was fitted with bayonets\n\n**Officer Assignments:**\n\n| Officer | Role |\n|---|---|\n| Lt. Col. S.C. Briggs | Military Secretary, overall control |\n| Capt. George Holms | Control of Madras Horse Artillery |\n| Capt. Allen Scott | Command of Hyderabad Contingent guns |\n| Capt. Bradley, 24th Regiment | Protection of Madras troops |\n| Major Thornhill & Capt. Campbell | Volunteer assistants to the Resident |\n\n*   Col. Davidson effectively turned the Residency into a Fort\n*   Salar Jung warned Davidson that a crowd assembled at Mecca Masjid might proclaim Jihad and begin rioting around 1 p.m. on Friday 17th July — this did not occur as feared\n*   At about 6 p.m., Salar Jung sent a spy to inform Davidson that 500 Rohillas under **Turrebaz Khan** and **Allauddin** were advancing toward the Residency\n\n**The Attack:**\n\n*   At 6 p.m., **600 armed men** marched on the Residency, led by **Jamedar Turrebaazkhan**; roads leading there turned into what is described as a sea of militant mutineers\n*   Every Residency gate was closed and patrolled\n*   Rohillas occupied two structures on the western side of the Residency — belonging to traders Jaigopal Das and Abbin Sahib — and also the area toward Dilsukh Gardens\n*   From these positions, they urged the Indian guards at the Residency Gate to secure Chidakhan''s release, expecting the guards to join them\n*   **Risaldar Ismail Khan** instead came forward to oppose the militants; surprised by his loyalty to the \"foreign masters,\" they fired at him, but he escaped\n*   Residency Commander Briggs''s strategy was not to attack the militants that night; the Arab Guards regiment sent by Salar Jung surrounded the occupied buildings\n*   Rohillas broke open adjoining walls and launched a ferocious attack, during which the **Putlibowli gate collapsed**\n*   Firing continued for about half an hour; Briggs retaliated with cannon fire, continuing until **4 a.m.**\n*   Under the severity of the retaliation, the Rohillas escaped into the darkness, aided by the Arab Guards\n*   **32 men of Madras Artillery died** of gunfire and injuries\n\n**Aftermath:** Militant leaders Turrebaz Khan and Maulvi Allauddin were declared offenders with a reward of 5,000 on them.\n\n*   **Turrebaz Khan**, while on the run, was arrested on 22nd July at Mogulaguda and produced before the Karmat Ali Magistrate Criminal Court, where Civil Court Magistrate Fazlulla recorded his statement\n    *   While being transferred to Andaman under a life sentence, he escaped at Mogiligidda in Mahbubnagar district, and was rearrested near Toopran with the help of Kurban Ali\n    *   At the time of his final capture, Turrebaz Khan refused to be taken alive and drew his sword to strike at Salar Jung''s soldiers; seeing his fearsome bearing, the soldiers did not hesitate and shot him down\n    *   His body was beheaded, and the head was bound with garlands and paraded to the main gate of the Residency as a trophy — a display meant to demonstrate to the public that the revolt had been crushed\n*   **Maulvi Allauddin** fled to Bangalore, was caught at Mangalapalli, tried, sentenced to life imprisonment, and sent to Andaman on 28th June 1859; he died there in 1884\n\nThe attack on the Residency ultimately **failed for lack of cooperation from the countrymen**.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p9", "partName": "The Rebellion and Conspiracy in Different Places of the State", "bodyMd": "The rebellion did not end with the failed attack on the Residency — disturbances continued in different parts of the State until 1860, fuelled further by the agents of **Nana Sahib**, **Tantiya Tope**, and **Raosahib Peshwa**, who went among the people preaching against the British.\n\n### Revolt of Raja Venkatappa Naik (Shorapur)\n\n*   Shorapur, an area under Gulbarga''s control, was ruled by descendants of the Bedar dynasty\n*   **Philips Meadows Taylor** was appointed political administrator and protector of Raja Venkatappa Naik after his father died while Naik was still a minor\n*   In 1853, once Naik was no longer a minor, Taylor handed over the reins of the Samasthanam and went to Hyderabad\n*   Shorapur was initially a Maratha area before coming under Nizam control\n*   During the 1857 revolt, Naik expected to become independent of both the Nizam and the British; **Nanasahib and the Zamindar of Raichur promised him help** and that he would be made king of the area from Shorapur to Rameswaram\n*   Motivated by these promises, the Raja took part in the rebellion, assembling a battalion of six hundred Rohillas and Arab fighters\n*   He ignored Col. Davidson''s letter demanding he cancel the mobilization; Davidson sent **Campbell**, whose order to disband the army was also disregarded\n*   To suppress the Raja, Campbell sent **Windhum and Col. Malcolm**; the battalion disintegrated, and the Raja fled to Hyderabad to meet Taylor, where he was caught\n*   **Col. Davidson awarded him the death penalty**, later commuted to life imprisonment through Taylor''s intervention; while being transferred to Chengalput near Madras, he committed suicide by shooting himself with a soldier''s gun\n\n### Rebellion by Malked Koppal\n\n*   Led by **Bhimrao**, Jamindar of Mundargi (also Tahsildar of Ballari, removed for bad conduct) and **Kenchan Gowda**, Desai of Hummigi — both located north of the Tungabhadra\n*   Bhimrao rebelled alongside the Desais of Sartur, Dambal (Srinivas Venkatadri), Hummigi (Kenchan Gowda), and Govinkos (Survada Goud)\n*   Bhimrao gathered 400 men under the pretext of digging a pond and obstructed British tax collection\n*   On investigation, the Collector of Bellari found large quantities of ammunition; using it, the rebels robbed the **Dambal Treasury** and destroyed government property in Gadag\n*   The British sent forces to Dharwad, Raichur, and Bellary; **Major Hews besieged Koppal Fort**, joined by forces of Major Pindar of Hyderabad and Lt. Taylor of Raichur\n*   Bhimrao, Kenchan Goud, and their accomplices **died in the battle of Koppal Fort on 1 June 1858**; 150 persons were jailed, subsiding the mutiny\n\n### Rebellion of Nargund Zamindar\n\n*   **Bhaskara Rao**, Zamindar of Nargund, rebelled with the aim of becoming independent, arranging a small battalion and killing British officer **Manson**\n*   He maintained good relations with Nanasahib; Jamindars of Bombay and Karnataka planned to rebel alongside Samasthana rulers on **27 May 1858**\n*   The British crushed the rebellion, arrested Bhaskara Rao, and took control of his Zamindari\n\n### The Case of Conspiracy by Rangarao\n\n*   In 1858, alongside the mutiny of Bhils and Gonds, a major conspiracy formed involving **Rangarao** (an agent of Nana Sahib), **Raja Deep Singh**, Zamindar of Koulas, and **Safdar-ud-Daula** — all connected to **Rao Rambha Nimbarkar**, a high official in the Nizam''s court\n*   Their plan was to launch a rebellion in the name of Nana Sahib Peshwa, but they lacked financial resources\n*   While the British were crushing the Rohillas, the conspiracy came to light: letters written by the Kaulas Raja and Safdar-ud-Daula were recovered during searches, including one from **Sonaji Pandit** (Daftardar under Roy Rayan of the Nizam''s court) addressed to Nana Sahib in Kanpur\n*   Sonaji Pandit was removed from service; he had been sending letters to Nana Sahib via **Rangarao Phage**, who in turn relayed letters from Nana Sahib to Zamindars, Patels, and Kulkarnis\n*   After Sonaji Pandit''s death on **26 February 1859**, Rangarao continued delivering letters to Hyderabad; en route, he met Deep Singh disguised as a doctor and secured his sympathy, then went to Maniknagar and met the Patels\n*   The British grew suspicious and arrested him at **Ankalska**; he had wanted to build an army of 10,000 men for Nana Sahib\n*   Rangarao, the King of Kaulas, and Safdar-ud-Daula were arrested and tried: **Rangarao was sent to Andaman**, **Safdar-ud-Daula received life imprisonment**, and **Rajdeep Singh received a three-year prison term**\n\n### Mutiny by Rohillas (Basmatinagar and Nirmal)\n\n*   Rohillas created disturbances in Basmatinagar and Nirmal, and Bhils did so in Ajanta, looting and setting fire to properties\n*   Serious riots occurred in **1858–59** in Ajanta, crushed indiscriminately by **Hewroj**\n*   Sporadic opposition continued until 1860, requiring continuous British deployment\n*   Rohilla leaders ultimately claimed to be operating under the leadership and control of **Nana Sahib**, moving village to village and displaying posters in populated areas\n\n### Ramji Gond Rebellion\n\n*   Another Rohilla-linked rebellion occurred at **Nirmal** in Adilabad district, led by **Ramjigond**\n*   He freed neighboring areas of Adilabad, made Nirmal his capital, and ruled\n*   A battle took place between the Collector''s forces and Rohillas/500 Gond troops at Nirmal in **April 1860**; many Rohillas and Gonds died in the firing\n*   Their leader Ramjigond escaped but was caught and tried, sentenced to death by hanging\n*   Along with him, his **one thousand associates were hanged from a banyan tree**, which became popularly known as _''veyyi urula marri''_ (banyan tree of a thousand hangings)\n\n### Mutiny by Bhils\n\n*   In 1857, Bhils rebelled in the Ajanta area under the leadership of **Bhagoji Nayak**, continuing attacks and burglaries through 1857\n*   **Vaijapur Deshpandes** assisted them in the burglaries; Contingent forces eventually prevented the burglaries and repressed the Bhils\n\n### The Case of Jahangir Khan\n\n*   After successfully repressing the 1857 mutiny, Col. Davidson went to Calcutta, where the Governor General sent a gift (\"kharita\") to the Nizam via the Resident\n*   While returning after presenting the gift on **15 March 1859**, **Jahangir Khan** fired at the Resident with a gun (missed), then attacked with a sword; the Resident''s guards overpowered him, and Jahangir Khan died due to torture by the security forces\n*   Some accounts place this attack against the backdrop of the honors the British were conferring on the Nizam around this period\n    *   When the Governor-General''s official letter/gift was being carried toward the Nizam, **Jahangir Khan**, a Rohilla warrior, viewed this display as a grave insult to the Nizam''s dignity and launched a furious attack on the Resident''s party\n    *   Owing to unfortunate circumstances, the attack is said to have struck the wrong target — a Nizam official standing near the intended mark — rather than the Resident himself\n    *   Though captured, Jahangir Khan reportedly showed no remorse for any punishment that might follow, and the true depth of the conspiracy behind him was never fully traced\n\n### The Kukatpalli Episode\n\n*   In **April 1859**, Army Officer **Kaston Macintray** was attacked by a returning soldier who pierced him with a sword; the soldier was caught and hanged without trial or inquiry\n*   Investigation revealed soldiers hostile to the British planning rebellion against both the Nizam and British — **Ajmat Jung, Mirdachand, Baajikhan, and Maulvi Ibrahim**\n*   Col. Davidson told the Nizam to exile Ajmat Jung, alleging he and Roshanuddaula (the Nizam''s brother) were trying to kill the Nizam\n*   **Mirdachand**, an officer in charge of the Chobdar branch under the Nizam administration, was not a direct participant but had been observing the Nizam''s movements; he had participated in the 17 July 1857 attack on the Residency and helped soldiers who wounded Brigadier Mekanjie at Bollaram Cantonment, and was a follower of Jahangir Khan\n*   **Baajikhan** sheltered mutineers in his house; **Maulvi Ibrahim** was trying to subdue the English people. All four were arrested and tried.\n\n### The Case of Conspiracy of Bhir\n\n*   **Bala Sahib**, a relative of Pratap Singh (king of Satara, whose kingdom had merged with the British Empire under the State Annexation Policy), came to Deccan with followers to start a rebellion, indulging in robbery and vile acts\n*   **Devrao Kishan, Vamanrao Kishan, Vithalrao alias Ambaji, Bhir Deshmukh, and Srinivas Sankarrao Deshpande** attempted rebellion against the British under Balasahib''s leadership and were sentenced to rigorous imprisonment after trial\n\n### Rao Sahib Peshwa (Begum Bazar Conspiracy)\n\n*   **Rao Sahib Peshwa** secretly came to Hyderabad in 1862, hiding in Begum Bazar after the failure of the rebellion in the North, protected by local people and traders\n*   Revolutionary **Kishan Rao** was already hiding in Begum Bazar; the two mobilized forces and presented shawls to those who joined them\n*   Associates included landlord **Rukmareddy** of Mortad (Armoor Taluka, Nizamabad district), priests **Lingayya and Antayya** and **Baldev Prasad, Madhura Prasad, Ganesh Singh** of Balamukund area (who worked in the British Army), and an anonymous lady the British could never identify despite extensive searches\n*   Many were arrested; **Rukmareddy, Tuljaram, and Ratansingh** were caught — Ratansingh escaped but committed suicide by poison when recaptured\n*   Rao Sahib and Kishanrao escaped; **Seth Mohanlal Pithi** hid Rao Sahib as a monk in a Gosai Mutt under Muslimjung bridge (he had earlier also rescued Puranmal, Turrebaz, and Maulvi Allauddin)\n*   The British arrested Seth Mohan Lal and Puranmul, fining them **75,000 and 10,000** respectively\n*   This episode is known as the **Begum Bazar conspiracy case**\' WHERE chapter_slug = 'telangana-history-en-chapter15-1857-revolt-in-hyderabad';
UPDATE theory_content SET concepts_json = concepts_json || 'n*   When Rao Sahib was traced to Narsingi in Medak District, police caught only a follower — the leader escaped again, but **Rao Sahib was ultimately caught in Kanpur and hanged in August 1862**\n\n### Khalki Conspiracy Case\n\n*   **Rama Rao alias Jung Bahadur** arranged hundreds of followers for the King of Satara, issuing them appointment letters (_Kaulnama_)\n*   The Government arrested his followers **Rama Rao, Bhimrao, Balakrishna, and Vithoba**, sending them to Andaman\n\n### Episode of Vasudev Balvant Phadke (1879)\n\n*   Noted Maratha rebel **Vasudev Balvant Phadke** toured the border districts of Gulbarga in 1879, requesting help from the Rohillas\n*   The Bombay Governor sent a telegram informing the Resident at Hyderabad; the Resident appointed **Abdul Haque** as Special Officer\n*   Phadke was arrested, tried, and sentenced to **seven years of rigorous imprisonment**\n\n### Rekapalli Rebellion\n\n*   Central districts had no restriction on Podu cultivation, taxed at four annas per axe; the **Madras Government enhanced this tax threefold**, imposing atrocious taxes on certain trees and causing severe hardship\n*   A rebellion broke out in **Rampa**; rebels attacked the Vaddegudem Police Station with help from **Ambulreddy**\n*   The Government sent forces in a steamer from Rajahmundry to punish them; discovering the steamer carried no arms, the rebels attacked it\n*   Police patrolling with 120 soldiers was introduced on the Godavari river, stopping the attacks\n*   As the rebellion subsided, the Government handed over local administration in **October 1880 to Tammidora**, who instead looted villagers\n*   Rebels from Rampa joined forces with Tammidora and influenced people in Rekapalli, together looting the **Palvancha Taluka treasury** and destroying neighboring police stations\n*   The Madras Government wrote to the Hyderabad Government warning that the Rampa rebels might reach Hyderabad from Rekapalli; the Collector of Khammam confirmed arrangements were made to arrest them\n*   **Salar Jung issued a farmana** on the Resident''s orders, naming Ramareddy, Ambulreddy, Kakurreddy, Bundel Dora, and Tammidora for arrest, with a reward of Rs 200\n*   Police surveillance was increased at both Madras and Hyderabad; the rebels escaped capture but stopped their activities under the pressure of enhanced security, and the rebellion **subsided within one year**\n\nEven after the formal end of the 1857 mutiny, its effects lingered in Hyderabad State for nearly twenty years, with the suppressed dissatisfaction among Makhtedaars, officers, and Zamindars continuing to surface through armed rebellions and, eventually, the National Movement for Independence.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p10", "partName": "Reasons for the Failure of the Rebellion", "bodyMd": "Lack of competent leadership, unity, and organizational strength among the rebels, combined with the Nizam and Salar Jung siding with the British, meant the rebellion in Hyderabad ultimately failed.\n\n**British Rewards to the Nizam and Salar Jung for Loyalty:**\n\n*   **Raichur, Antarvedi, and Naldurg** districts — taken from the Nizam in 1853 to maintain the Hyderabad Contingent — were returned; the British retained only Berar\n*   The **Shorapur Estate** was given to the Nizam\n*   A debt of **50 lakhs** was forfeited\n*   A new agreement was signed in **1860**, suitably modifying the original 1853 agreement\n*   The Nizam was gifted **ten thousand pound sterling**; Salar Jung received presents worth three thousand sterling\n*   The Nizam, in turn, sent gifts to the Governor General valuing fifteen thousand pound sterling\n*   The British announced the title **''The Star of India''** for the Nizam — though people opposed this and protested through posters across the city against the Nizam and the Diwan", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p11", "partName": "Result of the Mutiny", "bodyMd": "**On the Mughal Empire:**\n\n*   With the mutiny crushed, the Mughal Empire — which had existed only in name — formally ended; the last Mughal Emperor was sent to Burma (Rangoon)\n*   The Governor General advised the Nizam to introduce his own currency and coins; Nizam Bahadurshah initially refused to mint currency during his lifetime, but the Governor General did not yield\n*   Coins called **''haali sikka''** were released, bearing ''Nizam-Ul-Mulk Asafza Bahadur'' on one side and ''Julus Mymanath Jarb Farkunda Buniyad Hyderabad'' on the other\n*   **Khutba** was thereafter read in the name of Afzaluddaula, not the Emperor\n*   The post of Mughal Subedar in the Hyderabad Nizam''s Court was **abolished**\n*   The Nizam was pressured into declaring Hyderabad a **sovereign state**, marking the effective end of Mughal authority — though the word \"independence,\" meaningful in 1724, had become meaningless by 1858, since the Nizam remained far from a \"free bird\" under continuing British oversight\n\n**On British Policy Toward Princely States:**\n\n*   The British realized they needed to change their attitude toward the Samasthanams\n*   It was announced that the rights, special powers, dignity, and respect of Indian rulers would be treated as matters of honor for the British Government itself\n*   Lands belonging to mutineers were forcibly confiscated; titles and lands were instead granted to those who remained loyal to the British during 1857, as recognition of their loyalty and valuable service\n\n**Honors Conferred:**\n\n*   The Nizam was addressed as a trustworthy friend — **''Faithful Ally''** and **''Yaare Waffadar''**\n*   He was awarded the title **''Grand Commander Star of India''** on **30 August 1861**, along with the knighthood of the **''Most Exalted Order''**\n*   As part of the same honors, Resident **Davidson** presented the Nizam with a **portrait of Queen Victoria** in a specially arranged durbar — a gesture that, for a time, fostered in the Nizam the impression of being treated on equal footing with the British monarchy, though this sense of parity soon proved illusory as British interference only deepened afterward\n\n| Title/Honor | Recipient | Date/Detail |\n|---|---|---|\n| Grand Commander Star of India | Nizam | Conferred 30 August 1861 |\n| Faithful Ally / Yaare Waffadar | Nizam | Trustworthy friend address |\n| Presents worth three thousand sterling | Salar Jung | For loyalty during 1857 |\n\n**Long-Term Impact:**\n\n*   Even when the Government in England took direct control from the East India Company as a result of the mutiny, the relationship between the Nizam and the British saw no fundamental change\n*   British interference in Hyderabad''s affairs increased further\n*   The functioning of the Nizam''s \"sovereign\" state was restricted; at minimum, the sovereign ruler did not even have the right or power to appoint or remove his own ministers", "free": false}, {"partNumber": 12, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p12", "partName": "The Paloncha Samsthan Episode", "bodyMd": "*   In 1842, when the head of the **Paloncha Samsthanam** rebelled, the British seized the Samsthanam into their own territory without the Nizam''s knowledge\n*   As a mark of gratitude for the Nizam''s loyalty during the 1857 revolt, this Samsthanam was later returned to the Nizam\n*   The outstanding contingent dues of **50 lakhs** owed by the Nizam were also written off", "free": false}, {"partNumber": 13, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p13", "partName": "Salar Jung''s Later Power Struggle with the British", "bodyMd": "*   Despite the extensive help Salar Jung had rendered to the British, they were unwilling to see him grow too powerful\n*   Complete administrative authority resting in one man''s hands ran counter to British political interests\n*   With the sixth Nizam, **Mir Mahbub Ali**, still a six-year-old minor, the British appointed a rival co-guardian (contingent-in-charge) — **Shams-ul-Umra** — to check Salar Jung''s authority\n*   When Shams-ul-Umra died in 1877, the British appointed another rival in his place, **Vikar-ul-Umra**\n*   Salar Jung strongly opposed this appointment; the British warned him: \"If you do not accept this, we will arrest you and send you to Madras\"\n*   Faced with no alternative, Salar Jung was ultimately compelled to accept\n*   Whatever the case, in an era when the British had removed many rajas and nawabs who opposed them from power, it was the Nizams alone who managed to protect their kingdom by staying in the good graces of the British", "free": false}, {"partNumber": 14, "conceptId": "telangana-history-en-chapter15-1857-revolt-in-hyderabad-p14", "partName": "Change in Residency–Nizam Protocol After 1857", "bodyMd": "*   Once the crisis of 1857 had passed, the British began to conduct themselves with full authority\n*   Until 1857, whenever the Resident came to the Nizam''s court, he would remove his shoes and bow low, offering repeated salutations, out of deference to the Nizam; all such courtesies now ceased\n*   In official correspondence, the Governor-General had addressed the Nizam as **''Niyaz-mand''** (a humble petitioner) while the Nizam addressed the Governor-General as **''Mabadaulath''** (your lordship) — these forms of address were dropped entirely\n*   The Nizam''s hope of one day attaining a status equal to the British crown was thoroughly shattered\n*   From this point on, the Nizam became a wholly subordinate ally of the British", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter15-1857-revolt-in-hyderabad';
